def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 3:
                continue
            # Five-wide cap, centered two rows above the marker.
            for x in range(c-2, c+3):
                if 0 <= r-2 < h and 0 <= x < w:
                    out[r-2][x] = 5
            # Two side rails, each extending from one row above through
            # two rows below the marker.
            for y in range(r-1, r+3):
                for x in (c-2, c+2):
                    if 0 <= y < h and 0 <= x < w:
                        out[y][x] = 2
            # The row two below is filled across the entire canvas, with
            # the five cells between the rails colored 8.
            if 0 <= r+2 < h:
                for x in range(w):
                    out[r+2][x] = 8 if c-2 <= x <= c+2 else 2
    return out
PY
